<?php
require __DIR__ . '/guard.php';
use App\Guesstimate\Auth\AccessDenied;
use App\Guesstimate\Contracts\{ContractEvent, ContractService, ContractTemplateService, ContractValues, ContractVersion, DraftConflict, PaymentSchedule, TemplateDocument, TemplateVariables};
use App\Guesstimate\Offers\Offer;
use Illuminate\Support\Facades\DB;
$pass = 0; $fail = 0;
$ok = function (string $n, $c) use (&$pass, &$fail) { $c ? $pass++ : $fail++; echo($c ? '  ok  ' : ' FAIL '), $n, "\n"; };
$throws = function (callable $f, string $class = Throwable::class) { try { $f(); return false; } catch (Throwable $e) { return $e instanceof $class; } };
$msg = function (callable $f) { try { $f(); return ''; } catch (Throwable $e) { return $e->getMessage(); } };
wp_set_current_user(1);
$sum = fn () => [DB::table('gst_publications')->orderBy('id')->pluck('snapshot', 'id')->map(fn ($x) => md5($x))->all(), DB::table('gst_offer_versions')->orderBy('id')->get(['id', 'low_min', 'mid_min', 'mid_max', 'high_max', 'result'])->map(fn ($x) => md5(json_encode($x)))->all()];
$before = $sum();
$tok = fn ($k) => sprintf('<span class="ct-var" data-var="%s" contenteditable="false">%s</span>', $k, TemplateVariables::all()[$k]);
$s = app(ContractTemplateService::class); $c = app(ContractService::class);
$bodyT = TemplateDocument::compose('', '<p>Kwota ' . $tok('contract.amount') . ' / ' . $tok('contract.amount_gross') . '</p><p>' . $tok('payments.table') . '&nbsp;</p>', '');
$a = $s->approve($s->create('T10', $bodyT)->fresh());
$offer = Offer::whereNotNull('client_id')->whereNotNull('current_version_id')->orderByDesc('id')->get()->first(fn ($o) => $o->currentVersion?->result && $o->currentVersion->isBudget());
$k = $c->create($offer, $a, 'K'); $v = fn () => ContractVersion::find($k->fresh()->current_version_id);
$ok('nowa umowa bez narzuconego harmonogramu', $v()->data_snapshot['payments'] === [] && PaymentSchedule::forSnapshot($v()->data_snapshot)['stages'] === []);
$ok('brak kwoty nie jest wypełniany ceną oferty', ContractValues::resolved($v()->data_snapshot)['contract.amount'] === null);
$save = function (array $input) use ($c, $k, $v) { $p = PaymentSchedule::parse($input); if ($p['errors']) { throw new RuntimeException(json_encode($p['errors'])); } return $c->savePayments($k->fresh(), $p['payments'], $v()->snapshotHash()); };
$ok('brak harmonogramu przy tokenach blokuje', $throws(fn () => $c->approve($k->fresh()), InvalidArgumentException::class));
$ok('zły skrót blokuje zapis', $throws(fn () => $c->savePayments($k->fresh(), [], str_repeat('0', 64)), DraftConflict::class));
$base = ['agreed_net' => '10 000', 'vat_rate' => '23', 'stages' => [['name' => 'I', 'net' => '6000'], ['name' => 'II', 'net' => '3000']]];
$save($base);
$bodyB = $v()->body;
$ok('treść bez zmian po zapisie', $bodyB === $bodyT);
$ok('niezgodna suma blokuje', str_contains($msg(fn () => $c->approve($k->fresh())), 'różnica'));
$save(['stages' => [['name' => 'I', 'net' => '6000'], ['name' => 'II', 'net' => '4000']], 'deposit_net' => '1000'] + $base);
$ok('niewybrany zadatek blokuje', str_contains($msg(fn () => $c->approve($k->fresh())), 'zadatek'));
$save(['stages' => [['name' => 'I', 'net' => '6000', 'percent' => '30'], ['name' => 'II', 'net' => '4000', 'percent' => '70']], 'deposit_net' => '1000', 'deposit_mode' => 'separate'] + $base);
$ok('zadatek odrębny ponad kwotę blokuje', str_contains($msg(fn () => $c->approve($k->fresh())), 'różnica'));
$save(['stages' => [['name' => 'I', 'net' => '6000', 'percent' => '30', 'due' => '7 dni'], ['name' => 'II', 'net' => '4000', 'percent' => '70']], 'deposit_net' => '1000', 'deposit_mode' => 'credited', 'deposit_stage' => '1'] + $base);
$d = $v()->data_snapshot; $sm = PaymentSchedule::forSnapshot($d);
$ok('zaliczony bez podwójnego liczenia', $sm['blockers'] === [] && $sm['paid']['gross'] === 1230000 && $sm['deposit']['gross'] + array_sum(array_column($sm['stages'], 'payable')) === 1230000);
$ok('procenty zostają obok kwot, z ostrzeżeniem', $d['payments']['stages'][0]['percent'] === '30.00' && $d['payments']['stages'][0]['net'] === 600000 && count($sm['warnings']) >= 2);
$r = ContractValues::render($v()->body, $d);
$ok('tabela w treści', str_contains($r, '<table>') && str_contains($r, 'Do zapłaty') && ! str_contains($r, 'data-var'));
$ok('dziennik bez kwot', ! str_contains(json_encode(ContractEvent::where('contract_id', $k->id)->where('type', 'payments_saved')->pluck('payload')), '600000') && ContractEvent::where('contract_id', $k->id)->where('type', 'payments_saved')->count() >= 3);
$c->refresh($k->fresh(), $v()->snapshotHash());
$ok('odświeżenie zachowuje harmonogram', $v()->data_snapshot['payments'] === $d['payments']);
$ap = $c->approve($k->fresh());
$ok('zatwierdzenie mimo ostrzeżeń, skrót obejmuje kwoty', $ap->isApproved() && $ap->fresh()->isIntact());
$ok('zatwierdzonej nie można zmienić', $throws(fn () => $c->savePayments($k->fresh(), [], $ap->fresh()->snapshotHash()), InvalidArgumentException::class));
$raw = ContractVersion::find($ap->id)->getAttributes()['data_snapshot'];
DB::table('gst_contract_versions')->where('id', $ap->id)->update(['data_snapshot' => str_replace('1000000', '1000001', $raw)]);
$ok('podmiana kwoty wykryta skrótem', ContractVersion::find($ap->id)->getAttributes()['data_snapshot'] !== $raw && ! ContractVersion::find($ap->id)->isIntact());
DB::table('gst_contract_versions')->where('id', $ap->id)->update(['data_snapshot' => $raw]);
$n = $c->newVersion($k->fresh());
$ok('nowa wersja przenosi harmonogram', $n->data_snapshot['payments'] === $d['payments']);
$ok('v1 bez zmian', ContractVersion::find($ap->id)->getAttributes()['data_snapshot'] === $raw);
wp_set_current_user(get_user_by('login', 't8emp')->ID);
$ok('pracownik: cudzy harmonogram odrzucony', $throws(fn () => $c->savePayments($k->fresh(), [], $n->snapshotHash()), AccessDenied::class));
wp_set_current_user(1);
$ok('kwoty ofert i publikacje bez zmian', $sum() === $before);
echo "WYNIK: $pass ok, $fail błędów\n";
